import { useEffect, useState } from "react";

function Marks() {
  const [students, setStudents] = useState([]);
  const [marks, setMarks] = useState({});

  useEffect(() => {
    setStudents(JSON.parse(localStorage.getItem("students")) || []);
  }, []);

  const handleChange = (studentId, subject, value) => {
    setMarks({
      ...marks,
      [studentId]: {
        ...marks[studentId],
        [subject]: value
      }
    });
  };

  const saveMarks = () => {
    const storedMarks = JSON.parse(localStorage.getItem("marks")) || {};

    students.forEach(student => {
      storedMarks[student.id] = marks[student.id] || {};
    });

    localStorage.setItem("marks", JSON.stringify(storedMarks));
    alert("Marks saved successfully");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Enter Student Marks</h2>

      {students.map(student => (
        <div key={student.id} style={{ border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
          <b>{student.name}</b> (Roll: {student.roll})
          <br /><br />

          <input
            placeholder="Maths"
            type="number"
            onChange={e => handleChange(student.id, "Maths", e.target.value)}
          />
          <br /><br />

          <input
            placeholder="Science"
            type="number"
            onChange={e => handleChange(student.id, "Science", e.target.value)}
          />
          <br /><br />

          <input
            placeholder="English"
            type="number"
            onChange={e => handleChange(student.id, "English", e.target.value)}
          />
        </div>
      ))}

      <button onClick={saveMarks}>Save Marks</button>
    </div>
  );
}

export default Marks;
